     4	<meta charset="utf-8">
     5	<meta name="viewport" content="width=device-width, initial-scale=1">
     6	<title>Todos</title>
     7	<style>
     8	  * { box-sizing: border-box; }
     9	  body {
    10	    margin: 0;
    11	    font: 16px/1.4 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    12	    background: #f5f5f4;
    13	    color: #1c1917;
    14	  }
    15	  main {
    16	    max-width: 32rem;
    17	    margin: 3rem auto;
    18	    padding: 0 1rem;
    19	  }
    20	  h1 { font-size: 1.5rem; margin: 0 0 1rem; }
    21	  form { display: flex; gap: 0.5rem; }
    22	  input[type="text"] {
    23	    flex: 1;
    24	    min-width: 0;
    25	    padding: 0.6rem 0.75rem;
    26	    font: inherit;
    27	    border: 1px solid #d6d3d1;
    28	    border-radius: 6px;
    29	    background: #fff;
    30	  }
    31	  input[type="text"]:focus { outline: 2px solid #2563eb; outline-offset: -1px; border-color: transparent; }
    32	  button {
    33	    font: inherit;
    34	    padding: 0.6rem 1rem;
    35	    border: 0;
    36	    border-radius: 6px;
    37	    cursor: pointer;
    38	  }
    39	  .add { background: #2563eb; color: #fff; }
    40	  .add:hover { background: #1d4ed8; }
    41	  ul { list-style: none; margin: 1.25rem 0 0; padding: 0; }
    42	  li {
    43	    display: flex;
    44	    align-items: center;
    45	    gap: 0.75rem;
    46	    padding: 0.6rem 0.75rem;
    47	    background: #fff;
    48	    border: 1px solid #e7e5e4;
    49	    border-radius: 6px;
    50	    margin-bottom: 0.5rem;
    51	  }
    52	  .text { flex: 1; overflow-wrap: anywhere; }
    53	  .delete { background: transparent; color: #b91c1c; padding: 0.3rem 0.6rem; }
    54	  .delete:hover { background: #fee2e2; }
    55	  .empty { color: #78716c; margin-top: 1.25rem; }
    56	  .filters { display: flex; gap: 0.25rem; margin-top: 1rem; }
    57	  .filters button { background: transparent; color: #57534e; padding: 0.3rem 0.75rem; }
    58	  .filters button:hover { background: #e7e5e4; }
    59	  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; }
    60	  .toggle { width: 1.1rem; height: 1.1rem; margin: 0; flex: none; cursor: pointer; accent-color: #2563eb; }
