    64	<body>
    65	<main>
    66	  <h1>Todos</h1>
    67	  <form id="todo-form" autocomplete="off">
    68	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" aria-label="New todo">
    69	    <button data-testid="todo-add" class="add" type="submit">Add</button>
    70	  </form>
    71	  <div class="filters" role="group" aria-label="Filter todos">
    72	    <button data-testid="filter-all" type="button" data-filter="all" aria-pressed="true">All</button>
    73	    <button data-testid="filter-active" type="button" data-filter="active" aria-pressed="false">Active</button>
    74	    <button data-testid="filter-completed" type="button" data-filter="completed" aria-pressed="false">Completed</button>
    75	  </div>
    76	  <ul data-testid="todo-list"></ul>
    77	  <p class="empty" hidden>No todos yet.</p>
    78	</main>
    79	<script>
    80	(function () {
    81	  var STORAGE_KEY = 'todos';
    82	  var form = document.getElementById('todo-form');
    83	  var input = document.querySelector('[data-testid="todo-input"]');
    84	  var list = document.querySelector('[data-testid="todo-list"]');
    85	  var empty = document.querySelector('.empty');
    86	  var filterButtons = document.querySelectorAll('[data-filter]');
    87	  var filter = 'all';
    88	
    89	  function load() {
    90	    try {
    91	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
    92	      if (!Array.isArray(data)) return [];
    93	      return data.filter(function (t) {
    94	        return t && typeof t.id === 'string' && typeof t.text === 'string';
    95	      }).map(function (t) {
    96	        t.completed = t.completed === true;
    97	        return t;
    98	      });
    99	    } catch (e) {
   100	      return [];
   101	    }
   102	  }
   103	
   104	  function save() {
   105	    try {
   106	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
   107	    } catch (e) {
   108	      // Storage unavailable or full; keep working in memory.
   109	    }
   110	  }
   111	
   112	  function makeId() {
   113	    if (window.crypto && typeof crypto.randomUUID === 'function') {
   114	      try { return crypto.randomUUID(); } catch (e) { /* fall through */ }
   115	    }
   116	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
   117	  }
   118	
   119	  // Ordering rule (project decision): completed todos always sit below all
   120	  // active todos; each group keeps insertion order, oldest first. `todos` is
   121	  // stored in insertion order, so this is a stable partition.
   122	  function ordered() {
   123	    var active = todos.filter(function (t) { return !t.completed; });
   124	    var done = todos.filter(function (t) { return t.completed; });
   125	    return active.concat(done);
   126	  }
   127	
   128	  function visible(todo) {
   129	    if (filter === 'active') return !todo.completed;
   130	    if (filter === 'completed') return todo.completed;
   131	    return true;
   132	  }
   133	
   134	  function render() {
   135	    list.textContent = '';
   136	    var shown = ordered().filter(visible);
   137	    shown.forEach(function (todo) {
   138	      var li = document.createElement('li');
   139	      li.setAttribute('data-testid', 'todo-item');
   140	      li.setAttribute('data-id', todo.id);
   141	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
   142	
   143	      var box = document.createElement('input');
   144	      box.type = 'checkbox';
   145	      box.className = 'toggle';
   146	      box.setAttribute('data-testid', 'todo-toggle');
   147	      box.setAttribute('aria-label', 'Mark "' + todo.text + '" complete');
   148	      box.checked = todo.completed;
   149	      box.addEventListener('change', function () { toggle(todo.id); });
   150	
   151	      var span = document.createElement('span');
   152	      span.className = 'text';
   153	      span.setAttribute('data-testid', 'todo-text');
   154	      span.textContent = todo.text;
   155	
   156	      var del = document.createElement('button');
   157	      del.type = 'button';
   158	      del.className = 'delete';
   159	      del.setAttribute('data-testid', 'todo-delete');
   160	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
   161	      del.textContent = 'Delete';
   162	      del.addEventListener('click', function () { remove(todo.id); });
   163	
   164	      li.appendChild(box);
   165	      li.appendChild(span);
   166	      li.appendChild(del);
   167	      list.appendChild(li);
   168	    });
   169	    if (todos.length === 0) {
   170	      empty.textContent = 'No todos yet.';
   171	    } else if (filter === 'active') {
   172	      empty.textContent = 'No active todos.';
   173	    } else {
   174	      empty.textContent = 'No completed todos.';
   175	    }
   176	    empty.hidden = shown.length > 0;
   177	
   178	    filterButtons.forEach(function (btn) {
   179	      btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === filter ? 'true' : 'false');
   180	    });
   181	  }
   182	
   183	  function add(text) {
   184	    text = text.trim();
   185	    if (!text) return;
   186	    todos.push({ id: makeId(), text: text, completed: false, createdAt: Date.now() });
   187	    save();
   188	    render();
   189	  }
   190	
   191	  function remove(id) {
   192	    todos = todos.filter(function (t) { return t.id !== id; });
   193	    save();
   194	    render();
   195	  }
   196	
   197	  function toggle(id) {
   198	    todos.forEach(function (t) {
   199	      if (t.id === id) t.completed = !t.completed;
   200	    });
   201	    save();
   202	    render();
   203	  }
   204	
   205	  var todos = load();
   206	
   207	  filterButtons.forEach(function (btn) {
   208	    btn.addEventListener('click', function () {
   209	      filter = btn.getAttribute('data-filter');
   210	      render();
   211	    });
   212	  });
   213	
   214	  form.addEventListener('submit', function (e) {
   215	    e.preventDefault();
   216	    add(input.value);
   217	    input.value = '';
   218	    input.focus();
   219	  });
   220	
   221	  render();
   222	})();
   223	</script>
   224	</body>
   225	</html>
