const url = 'file:///Users/vmysla/src/product-tracebility-ab-testing/ab-study/arms/todo-rep-control-03/control/index.html';
setTimeout(() => { console.log('HARD TIMEOUT'); process.exit(2); }, 60000);
(async () => {
  const browser = await chromium.launch();
  // LA 23:30 local on the 13th is already the 14th in UTC.
  // Auckland 00:10 local on the 13th is still the 12th in UTC.
  const cases = [
    ['America/Los_Angeles', '2026-09-13T23:30:00-07:00'],
    ['Pacific/Auckland', '2026-09-13T00:10:00+12:00'],
  ];
  for (const [tz, clock] of cases) {
    const ctx = await browser.newContext({ timezoneId: tz });
    const page = await ctx.newPage();
    await page.clock.install({ time: new Date(clock) });
    const errors = [];
    page.on('pageerror', e => errors.push(e.message));
    await page.goto(url, { timeout: 10000 });
    const add = async (text, due) => {
      await page.fill('[data-testid="todo-input"]', text);
      if (due) await page.fill('[data-testid="todo-due"]', due);
      await page.click('[data-testid="todo-add"]');
    };
    await add('yesterday', '2026-09-12');
    await add('today', '2026-09-13');
    await add('tomorrow', '2026-09-14');
    await add('none');
    const rows = () => page.$$eval('[data-testid="todo-item"]', els => els.map(li => [
      li.querySelector('[data-testid="todo-text"]').textContent,
      li.dataset.overdue,
      li.querySelector('[data-testid="todo-due-date"]')?.textContent ?? '-',
    ]));
    console.log(tz);
    console.log('  rows:', JSON.stringify(await rows()));
    console.log('  due input after add:', JSON.stringify(await page.inputValue('[data-testid="todo-due"]')));
    const stored = JSON.parse(await page.evaluate(() => localStorage.getItem('todos')));
    console.log('  stored due:', JSON.stringify(stored.map(t => t.due)));
    await page.reload();
    console.log('  after reload:', JSON.stringify(await rows()));
    // LA only: advance past local midnight; "today" should flip to overdue.
    if (tz === 'America/Los_Angeles') {
      await page.clock.runFor(35 * 60 * 1000);
      console.log('  after midnight:', JSON.stringify((await rows()).map(r => r[0] + '=' + r[1])));
    }
    console.log('  errors:', errors);
    await ctx.close();
  }
  await browser.close();
  process.exit(0);
})().catch(e => { console.log('ERR', e.message); process.exit(1); });

